mapper.select:
SELECT /* homes.broker.mapper.BrokerBuldMapper.getBuldEtcCount */
       COUNT(1) AS CNT 
FROM   TB_BRK_BULD_ETC
WHERE  OFFICENO = #{officeno}
AND    HPSNO = #{hpsno}

mapper.update:
UPDATE /* homes.broker.mapper.BrokerBuldMapper.updateBuldEtc */ 
TB_BRK_BULD_ETC
SET    UPDT_USER_NO = #{mngrno}
       , UPDT_DT = CURRENT_TIMESTAMP()
       , BRKNO = #{brkno} 

       , OCCPGB = #{occpgb}


      , EXPIREDE = REPLACE(#{expirede}, '.', '')
      , CRTC_YY = #{crtcyy}
      , CRTC_MM = #{crtcmm}
      , CRTC_AT = #{crtcAt}

WHERE  OFFICENO = #{officeno}
AND    HPSNO = #{hpsno}

mapper.insert:
INSERT /* homes.broker.mapper.BrokerBuldMapper.insertBaseBuldEtc */
INTO   TB_BRK_BULD_ETC (
	OFFICENO, HPSNO, BRKNO, CREAT_USER_NO, UPDT_USER_NO
) VALUES (
	#{officeno}
	, #{hpsno}
	, #{brkno}
	, #{mngrno}
	, #{mngrno}
)
